package os_test

import (
	"testing"

	"github.com/vishnukv64/gpython/pytest"
)

// TestPathGolden runs a table generated by CPython's own posixpath and
// ntpath (testdata/genpathgolden.py).  Both modules are host independent, so
// the same table must pass on every OS.
func TestPathGolden(t *testing.T) {
	pytest.RunScript(t, "./testdata/pathgolden_run.py")
}
